<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{GoodsReceivedNote,InventoryItem,PurchaseReturn,Store,Supplier};use App\Services\Procurement\ProcurementService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PurchaseReturnController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.returns.index',['rows'=>PurchaseReturn::with(['supplier','store','items.inventoryItem'])->where('property_id',$p)->latest()->paginate(30),'suppliers'=>Supplier::where('property_id',$p)->where('is_active',1)->get(),'stores'=>Store::where('property_id',$p)->where('is_active',1)->get(),'items'=>InventoryItem::where('property_id',$p)->where('is_active',1)->orderBy('name')->get(),'grns'=>GoodsReceivedNote::where('property_id',$p)->where('status','posted')->get()]);}public function store(Request $r){$d=$r->validate(['supplier_id'=>'required|integer','store_id'=>'required|integer','goods_received_note_id'=>'nullable|integer','reason'=>'nullable','inventory_item_id'=>'required|array|min:1','quantity'=>'required|array','quantity.*'=>'required|numeric|min:.0001','unit_cost'=>'nullable|array']);DB::transaction(function()use($d){$ret=PurchaseReturn::create(['property_id'=>auth()->user()->property_id,'supplier_id'=>$d['supplier_id'],'store_id'=>$d['store_id'],'goods_received_note_id'=>$d['goods_received_note_id']??null,'number'=>'RET-'.now()->format('Ymd-His').'-'.random_int(10,99),'return_date'=>today(),'status'=>'approved','reason'=>$d['reason']??null,'created_by'=>auth()->id()]);foreach($d['inventory_item_id'] as $i=>$id)$ret->items()->create(['inventory_item_id'=>$id,'quantity'=>$d['quantity'][$i],'unit_cost'=>$d['unit_cost'][$i]??0,'reason'=>$d['reason']??null]);});return back()->with('success','Purchase return created.');}public function post(PurchaseReturn $return,ProcurementService $svc){abort_unless($return->property_id===auth()->user()->property_id,403);$svc->postReturn($return,auth()->id());return back()->with('success','Purchase return posted and stock reduced.');}}
